            rr,cc=stack.pop()
            if not(0<=rr<H and 0<=cc<W) or (rr,cc) in seen or I[rr][cc]==0: continue
            seen.add((rr,cc)); cs.append((rr,cc))
            stack+= [(rr+1,cc),(rr-1,cc),(rr,cc+1),(rr,cc-1)]
        return cs
    for r in range(H):
        for c in range(W):
            if I[r][c]!=0 and (r,c) not in seen:
                cs=comp(r,c)
                rs=[a for a,b in cs]; cl=[b for a,b in cs]
